state:
{% set h = now().hour + now().minute / 60 %}
{% set elev = state_attr('sun.sun', 'elevation') | float(0) %}
{% set wind = 1 if h < 5 else ([0, [1, (h - 21) / 1.5] | min] | max if elev < -4 else 0) %}
{% set top = states('input_number.desk_lamp_max_brightness') | float(55) %}
{% set d = states('sensor.outdoor_daylight') | float(0) / 100 %}
{% set level = (top * (1 - 0.65 * d)) * (1 - wind) + top * 0.45 * wind %}
{% if is_state('media_player.smart_tv_pro', 'on') %}{% set level = [level, top * 0.35] | min %}{% endif %}
{{ [10, level] | max | round(0) | int }}
